<script setup>
import {ref,onMounted} from 'vue';
import {listTrainingDatasets,saveTrainingDataset} from '../../services/trainingDatasets.js';
const props=defineProps({purpose:{type:String,default:'personal'},disabled:Boolean});
const emit=defineEmits(['use']);
const datasets=ref([]),name=ref(''),kind=ref('text'),text=ref(''),prompt=ref(''),completion=ref(''),rows=ref([]),error=ref(''),busy=ref(false),notice=ref('');
onMounted(async()=>{try{datasets.value=await listTrainingDatasets();}catch(e){error.value=e.message;}});
function add(){error.value='';notice.value='';if(kind.value==='text'){if(!text.value.trim())return;rows.value.push({text:text.value.trim()});text.value='';}else{if(!prompt.value.trim()||!completion.value.trim())return;rows.value.push({prompt:prompt.value.trim(),completion:completion.value.trim()});prompt.value='';completion.value='';}}
async function importFiles(event){error.value='';busy.value=true;try{const imported=[];for(const file of event.target.files||[]){if(!/\.(txt|md)$/i.test(file.name))throw Error('Choose text (.txt) or Markdown (.md) files.');if(file.size>1024*1024)throw Error('Keep each source file below 1 MB.');const text=await file.text();if(text.trim())imported.push({text:text.trim()});}if(!imported.length)throw Error('These files contain no text.');rows.value.push(...imported);notice.value=`Added ${imported.length} source files. Review the examples before saving.`;}catch(e){error.value=e.message;}finally{busy.value=false;event.target.value='';}}
async function save(){busy.value=true;error.value='';try{const saved=await saveTrainingDataset({name:name.value,purpose:props.purpose,rows:JSON.parse(JSON.stringify(rows.value))});datasets.value.push(saved);rows.value=[];name.value='';notice.value='Dataset saved on this device. Choose Use for training when you are ready.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template>
<section class="dataset-studio" aria-label="My datasets">
 <div class="dataset-heading"><div><h2 class="bz-h2">Turn Your Content Into Training Examples</h2><p>{{ purpose==='company'?'Capture how your team handles sales, customer service, accounting, operations and product delivery.':'Bring scripts, stories, creative briefs and other text examples. Teach the model the creative choices you want it to make.' }}</p></div></div>
 <p class="dataset-hint">This builder currently supports text datasets. Image, audio and video training require their own compatible pipelines and datasets; media files cannot be trained through this text form.</p>
 <div class="dataset-columns">
 <section class="dataset-editor">
 <h3>Create a Dataset</h3>
 <label>Dataset name<input v-model="name" :disabled="disabled||busy" placeholder="e.g. My creative style or Customer service playbook" /></label>
 <div class="dataset-actions"><label class="bz-btn dataset-import"><span class="material-symbols-outlined" aria-hidden="true">upload_file</span>Add text files<input type="file" multiple accept=".txt,.md" aria-label="Add text files" :disabled="disabled||busy" @change="importFiles" /></label><span>TXT / Markdown · one file per example</span></div>
 <label>Example type<select v-model="kind" :disabled="disabled||busy"><option value="text">My own content or reference text</option><option value="response">Request and ideal response</option></select></label>
 <label v-if="kind==='text'">Your content<textarea v-model="text" :disabled="disabled||busy" rows="6" placeholder="Paste a complete text example of your own content or a procedure you want the model to learn." /></label>
 <template v-else><label>Request or situation<textarea v-model="prompt" :disabled="disabled||busy" rows="3" placeholder="What should the model respond to?" /></label><label>Ideal response<textarea v-model="completion" :disabled="disabled||busy" rows="5" placeholder="Write the response you would want it to produce, in your style and following your methods." /></label></template>
 <button class="bz-btn" :disabled="disabled||busy||(kind==='text'?!text.trim():!prompt.trim()||!completion.trim())" @click="add">Add example</button>
 <details v-if="rows.length" open class="dataset-review"><summary>Review {{ rows.length }} examples</summary><article v-for="(row,index) in rows" :key="index"><div><strong>Example {{ index+1 }}</strong><p v-if="row.prompt">{{ row.prompt }}</p><pre>{{ row.text || row.completion }}</pre></div><button class="bz-iconbtn" :disabled="disabled||busy" :aria-label="`Remove example ${index+1}`" @click="rows.splice(index,1)"><span class="material-symbols-outlined">close</span></button></article></details>
 <p class="dataset-hint">Choose examples you want repeated. Remove confidential details you do not want learned, and keep a few examples aside to evaluate the result.</p>
 <button class="bz-btn bz-btn--primary" :disabled="disabled||busy||!name.trim()||!rows.length" @click="save">{{ busy?'Saving…':'Save dataset locally' }}</button>
 </section>
 <section class="dataset-library"><h3>Your Datasets</h3><p v-if="!datasets.length">Save your first collection here, then use it to customize a model. No wallet or publishing required.</p><article v-for="dataset in datasets" :key="dataset.id"><strong>{{ dataset.name }}</strong><span>{{ dataset.rows.length }} examples · {{ dataset.purpose==='company'?'Company methods':'Creative style' }}</span><button class="bz-btn" :disabled="disabled||busy" @click="emit('use',dataset)">Use for training<span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span></button></article></section>
 </div><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
</section>
</template>
<style scoped>
.dataset-studio{min-width:0}.dataset-heading{margin-bottom:24px}.dataset-heading p,.dataset-hint,.dataset-library p{color:var(--bz-fg-mid);font-size:14px;line-height:1.6}.dataset-columns{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(240px,1fr);gap:28px}.dataset-editor,.dataset-library{min-width:0}.dataset-editor{display:flex;flex-direction:column;align-items:stretch;gap:16px}.dataset-editor h3,.dataset-library h3{font:900 italic 24px/1.2 var(--bz-font-metric);margin:0 0 8px}.dataset-editor label{display:grid;gap:8px;font-size:13px}.dataset-editor input,.dataset-editor textarea,.dataset-editor select{width:100%;min-width:0;box-sizing:border-box;border:1px solid var(--bz-border-strong);border-radius:8px;background:var(--bz-panel);color:var(--bz-fg);font:inherit;padding:12px}.dataset-editor textarea{resize:vertical}.dataset-editor>button{align-self:flex-start}.dataset-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.dataset-actions>span{font-size:12px;color:var(--bz-fg-mid)}.dataset-import{position:relative;display:inline-flex!important;cursor:pointer}.dataset-import input{position:absolute;inset:0;opacity:0;cursor:pointer}.dataset-import:focus-within{outline:2px solid var(--bz-accent)}.dataset-review article{display:flex;gap:12px;padding:16px 0;border-bottom:1px solid var(--bz-border)}.dataset-review article>div{min-width:0;flex:1}.dataset-review pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:180px;overflow:auto;font:inherit;font-size:13px;color:var(--bz-fg-mid)}.dataset-library{border-left:1px solid var(--bz-border);padding-left:28px}.dataset-library article{display:grid;gap:12px;padding:20px 0;border-bottom:1px solid var(--bz-border);overflow-wrap:anywhere}.dataset-library article>span{font-size:13px;color:var(--bz-fg-mid)}.dataset-library button{justify-self:start}.dataset-review summary{cursor:pointer}@media(max-width:800px){.dataset-columns{grid-template-columns:1fr}.dataset-library{border-left:0;border-top:1px solid var(--bz-border);padding:24px 0 0}}
</style>
